import { realpath } from 'node:fs/promises';
import { createRequire } from 'node:module';
import path from 'node:path';
import { rolldown } from 'rolldown';
import { parseSync, Visitor } from 'rolldown/utils';
import { moduleReferences } from '../module-imports.mjs';

export const previewSandboxBanner =
  '/* Generated by scripts/build-page.mjs. Source: apps/extension/src/preview-sandbox. */';

const forbiddenPreviewApis = new Set([
  'chrome',
  'browser',
  'eval',
  'Function',
  'fetch',
  'importScripts',
  'require',
  'XMLHttpRequest',
  'WebSocket',
  'Worker',
  'SharedWorker',
  'EventSource',
]);

function unwrapExpression(node) {
  let expression = node;

  while (['ParenthesizedExpression', 'ChainExpression'].includes(expression.type)) {
    expression = expression.expression;
  }

  return expression;
}

function staticString(node) {
  const expression = unwrapExpression(node);

  if (expression.type === 'Literal' && typeof expression.value === 'string') {
    return expression.value;
  }

  if (expression.type === 'TemplateLiteral' && expression.expressions.length === 0) {
    const value = expression.quasis[0]?.value.cooked;

    if (typeof value === 'string') {
      return value;
    }
  }

  if (expression.type === 'BinaryExpression' && expression.operator === '+') {
    const left = staticString(expression.left);
    const right = staticString(expression.right);

    if (left !== undefined && right !== undefined) {
      return left + right;
    }
  }

  return undefined;
}

export function checkPreviewSandboxBundle(source, filename = 'preview-sandbox.js') {
  if (!source.startsWith(previewSandboxBanner)) {
    throw new Error('The preview sandbox is not a generated asset. Run pnpm build:host before packaging.');
  }

  const parsed = parseSync(filename, source);

  if (parsed.errors.length > 0) {
    throw new Error('Cannot inspect the generated preview sandbox. Rebuild before packaging.');
  }

  let offset = 0;

  if (parsed.program.body[0]?.directive === 'use strict') {
    offset = 1;
  }

  const statement = parsed.program.body[offset];
  const expression = statement?.expression;
  let callee = expression?.callee;

  while (callee?.type === 'ParenthesizedExpression') {
    callee = callee.expression;
  }

  const strict = offset === 1 || callee?.body?.body?.[0]?.directive === 'use strict';
  const classicIife =
    strict &&
    parsed.program.body.length === offset + 1 &&
    statement?.type === 'ExpressionStatement' &&
    expression?.type === 'CallExpression' &&
    ['ArrowFunctionExpression', 'FunctionExpression'].includes(callee?.type);

  if (!classicIife || moduleReferences(source, filename).length > 0) {
    throw new Error('The preview sandbox must be one self-contained classic IIFE without runtime imports.');
  }

  new Visitor({
    ImportExpression() {
      throw new Error('The preview sandbox cannot load runtime modules.');
    },
    MetaProperty(node) {
      if (node.meta.name === 'import') {
        throw new Error('The preview sandbox cannot require module execution.');
      }
    },
    Identifier(node) {
      if (forbiddenPreviewApis.has(node.name)) {
        throw new Error(
          'The preview sandbox cannot retain privileged, dynamic-code, or network API references.',
        );
      }
    },
    MemberExpression(node) {
      let property = node.property.name;

      if (node.computed) {
        property = staticString(node.property);
      }

      // A sensitive property is forbidden even when its receiver is an alias of a global object.
      if (forbiddenPreviewApis.has(property)) {
        throw new Error(
          'The preview sandbox cannot use privileged, dynamic-code, or network API properties.',
        );
      }

      const object = unwrapExpression(node.object);

      if (
        node.computed &&
        property === undefined &&
        object.type === 'Identifier' &&
        ['window', 'self', 'globalThis'].includes(object.name)
      ) {
        throw new Error('The preview sandbox cannot use nonliteral computed global lookups.');
      }
    },
    CallExpression(node) {
      if (
        node.callee.type === 'Identifier' &&
        ['eval', 'Function', 'fetch', 'importScripts', 'require'].includes(node.callee.name)
      ) {
        throw new Error('The preview sandbox cannot evaluate code or load remote runtime resources.');
      }
    },
    NewExpression(node) {
      if (
        node.callee.type === 'Identifier' &&
        ['Function', 'XMLHttpRequest', 'WebSocket', 'Worker', 'SharedWorker', 'EventSource'].includes(
          node.callee.name,
        )
      ) {
        throw new Error('The preview sandbox cannot open runtime network or worker resources.');
      }
    },
  }).visit(parsed.program);
}

function inside(directory, filename) {
  const relative = path.relative(directory, filename);

  return relative !== '..' && !relative.startsWith('..' + path.sep) && !path.isAbsolute(relative);
}

/** Only the isolated entry, its one shared wire contract, and installed Zod Mini enter this asset. */
export async function previewSandboxBundle(root) {
  const sourceRoot = await realpath(root);
  const sandboxDirectory = path.join(sourceRoot, 'apps/extension/src/preview-sandbox');
  const sharedSchema = path.join(sourceRoot, 'packages/ui/src/preview/sandbox-messages.ts');
  const require = createRequire(path.join(sourceRoot, 'package.json'));
  const zodDirectory = await realpath(path.dirname(require.resolve('zod/package.json')));

  const bundle = await rolldown({
    cwd: sourceRoot,
    input: path.join(sandboxDirectory, 'entry.ts'),
    platform: 'browser',
    external(source, importer, resolved) {
      if (
        importer &&
        !resolved &&
        source !== 'zod/mini' &&
        !source.startsWith('.') &&
        !path.isAbsolute(source)
      ) {
        throw new Error('An unsupported dependency entered the preview sandbox build: ' + source);
      }

      return false;
    },
    onwarn(warning) {
      throw new Error('The isolated preview sandbox build reported a warning: ' + warning.message);
    },
    plugins: [
      {
        name: 'confined-preview-sandbox',

        moduleParsed(module) {
          if (
            !inside(sandboxDirectory, module.id) &&
            module.id !== sharedSchema &&
            !inside(zodDirectory, module.id)
          ) {
            throw new Error('A module escaped the isolated preview sandbox build: ' + module.id);
          }
        },
      },
    ],
  });

  try {
    const generated = await bundle.generate({
      format: 'iife',
      strict: true,
      codeSplitting: false,
      banner: previewSandboxBanner,
    });
    const chunk = generated.output[0];

    if (generated.output.length !== 1 || chunk?.type !== 'chunk') {
      throw new Error('The preview sandbox build must produce exactly one classic script.');
    }

    checkPreviewSandboxBundle(chunk.code);

    return chunk.code;
  } finally {
    await bundle.close();
  }
}
